// ============================================================
// Rule: THM_Nailaolocker Ransomware Log File Created in ProgramData
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Nailaolocker Ransomware Log File Created in ProgramData.
// Severity: SEV_050_CRITICAL
// Category: DROPPER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0009 - Collection
// Technique: T1074.001 - Data Staged: Local Data Staging

// Desabilita diferenciação entre maiúsculas e minúsculas para comparações
config case_sensitive = false  

// Define o dataset de origem como dados brutos do Cortex XDR
| dataset = xdr_data  

// Filtra apenas eventos de arquivos
| filter event_type = ENUM.FILE  

// Restringe para eventos de criação de novo arquivo
| filter event_sub_type = ENUM.FILE_CREATE_NEW  

// Busca criação de arquivos "lock.log" dentro do diretório ProgramData
// Um padrão comum em malwares que usam logs ou arquivos de controle para execução
| filter action_file_name = "lock.log"  
       and action_file_path contains "ProgramData"  

// Restringe a processos não assinados digitalmente, um indicador adicional de suspeita
| filter actor_process_signature_status = ENUM.UNSIGNED  

// Seleciona os campos relevantes para análise
| fields agent_hostname,                     // Nome do host onde ocorreu o evento
         actor_process_image_name,           // Nome do processo responsável pela criação
         actor_process_image_path,           // Caminho completo do processo
         actor_process_image_sha256,         // Hash SHA256 do binário do processo
         action_file_name,                   // Nome do arquivo criado
         action_file_path                    // Caminho completo do arquivo criado
